1	type Item = { type: string };
2	
3	const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };
4	
5	const BLOCK_SIZE = 3;
6	const BLOCK_PREMIUM = 60;
7	
8	const basePremiumForItem = (item: Item): number => basePremiumsByType[item.type];
9	
10	const sumOfItemBasePremiums = (items: Item[]): number =>
11	  items.reduce((sum, item) => sum + basePremiumForItem(item), 0);
12	
13	const groupByType = (items: Item[]): Item[][] => {
14	  const groups = new Map<string, Item[]>();
15	  for (const item of items) {
16	    const group = groups.get(item.type) ?? [];
17	    group.push(item);
18	    groups.set(item.type, group);
19	  }
20	  return [...groups.values()];
21	};
22	
23	const basePremiumForGroup = (group: Item[]): number =>
24	  group.length === BLOCK_SIZE ? BLOCK_PREMIUM : sumOfItemBasePremiums(group);
25	
26	export const basePremium = (items: Item[]): number =>
27	  groupByType(items).reduce((sum, group) => sum + basePremiumForGroup(group), 0);
28	
29	const PROCESSING_FEE = 5;
30	
31	type QuoteStep = { op: "quote"; items: Item[] };
32	type Scenario = { customer: { yearsWithMHPCO: number }; steps: QuoteStep[] };
33	
34	export const runScenario = (scenario: Scenario): { results: { premium: number }[] } => {
35	  const results = scenario.steps.map((step) => ({
36	    premium: basePremium(step.items) + PROCESSING_FEE,
37	  }));
38	  return { results };
39	};
